static OrderCheck.Result check(List<Message> processed) {
    Set<Message> seen = new HashSet<>();               // equal by key and seq
    Map<String, Integer> highest = new HashMap<>();    // account -> highest seq booked so far
    int duplicates = 0, inversions = 0;
    for (Message m : processed) {
        if (!seen.add(m)) { duplicates++; continue; }  // booked before: a redelivery after a lost ack
        Integer top = highest.get(m.getKey());
        if (top != null && m.getSeq() < top) inversions++;
        else highest.put(m.getKey(), m.getSeq());
    }
    return new OrderCheck.Result(processed.size(), duplicates, inversions);
}

